templates.template:
/* [BZ] MenuFlex Font Awesome Menu Icons Base Styles BEGIN */
.p-nav-list .p-navEl-link, .p-nav-list .p-navEl.is-selected .p-navEl-link {
	// Padding between Main Menu options; XenForo default is 15px
	padding-left: 12px;
    padding-right: 12px;
}

.menu-content a.menu-linkRow, .p-sectionLinks-list a.p-navEl-link, .p-staffBar a.p-staffBar-link, .block-tabHeader .tabs-tab, .tabs.tabs--standalone .tabs-tab {
    &:before {
		// Padding between Icon and Menu Item Text for Submenus and Tabs
        padding-right: 3px;
	}
}
/* [BZ] MenuFlex Font Awesome Menu Icons Base Styles END */

// [BZ] MenuFlex Final Compiled Styles - Last Updated: Never
// Do not make changes within this template, they will be overwritten next time you save MenuFlex settings.

// Open Menus On Hover Disabled
// Tiered Menus Disabled
// Font Awesome Menu Icons Disabled

// [BZ] MenuFlex Final Compiled Styles - END

@media (any-hover: hover) {
    .menu {
        opacity: 0;
        transition: opacity 0s linear 0.1s; // match bzmf_openmenusonhover.js hoverDelay
    }

    .is-menuOpen .menu {
        opacity: 1;
    }

    li:not(.is-menuOpen) .menu {
        display: none;
    }

	<xf:if is="!{$xf.options.bzmf_tieredmenus}">
        .menu--structural .menu-content .nav-popout .menu-separator:last-child {
            display: block !important;
        }
    </xf:if>
}

/* [BZ] MenuFlex Tiered Menu BEGIN */
@media all and (min-width: 651px) {
    .menu--structural .menu-content {
        overflow: visible;

        > .nav-popout {
            position: relative;

            &:hover > .nav-popout--menu,
            &:focus-within > .nav-popout--menu {
                display: block !important;
                opacity: 1 !important;
                transition: opacity .25s ease, box-shadow .25s ease, transform .25s ease;
                box-shadow: 0 8px 20px rgba(0, 0, 0, 0.25);
                transform: translateY(-2px);
            }

            .nav-popout--menu .nav-popout:hover > .nav-popout--menu,
            .nav-popout--menu .nav-popout:focus-within > .nav-popout--menu {
                display: block !important;
                opacity: 1 !important;
                transition: opacity .25s ease, box-shadow .25s ease, transform .25s ease;
                box-shadow: 0 8px 20px rgba(0, 0, 0, 0.25);
                transform: translateY(-2px);
            }

            .nav-container {
                position: relative;
                display: flex;
                align-items: center;
                transition: background-color .2s ease;

                .menu-linkRow {
                    flex: 1;
                    word-wrap: break-word;
                    overflow-wrap: break-word;
                    white-space: normal;
                    line-height: 1.4;
                    padding: 5px;
                    transition: background-color .2s ease, color .2s ease;
                }

                a.offCanvasMenu-link {
                    padding: 0 10px;
                }

                a.offCanvasMenu-link--splitToggle {
                    &:before {
                        top: 2px;
                        bottom: 2px;
                    }

                    &:after {
                        .m-faContent(@fa-var-solid-caret-right, 1.2em);
                        height: 1.2em;
                        display: block;
        				transform-origin: 47% 50%;
        				transition: transform .2s ease;
                    }

                    &.is-active:after,
                    &.is-hovered:after {
                        transform: rotate(90deg);
                    }
                }

                &:hover {
                    background: @xf-contentHighlightBg;

                    & a.offCanvasMenu-link.offCanvasMenu-link--splitToggle:after {
                        transform: rotate(90deg);
                    }

                    & a.menu-linkRow[data-nav-id]:before {
                        transition: color .2s ease, transform .2s ease;
                        transform: scale(1.2);
                        color: xf-darken(@xf-linkColor, 10%);
                    }
                }

                & .menu-linkRow:hover ~ a.offCanvasMenu-link.offCanvasMenu-link--splitToggle:after {
                    transform: rotate(90deg);
                }
            }

            .nav-popout--menu {
                display: none;
                position: absolute;
                width: 250px;
                background: #FFFFFF !important;
                border: none;
                border-top: 2px solid @xf-paletteColor1;
                box-shadow: 0 5px 15px rgba(0, 0, 0, 0.2);
                border-radius: 3px;
                right: -250px;
                top: 0;
                z-index: 10;
                opacity: 0;
                transition: opacity .25s ease, box-shadow .25s ease, transform .25s ease;
            }

            & .nav-container:has(a.offCanvasMenu-link.offCanvasMenu-link--splitToggle.is-active) ~ .nav-popout--menu,
            .nav-popout--menu .nav-popout .nav-container:has(a.offCanvasMenu-link.offCanvasMenu-link--splitToggle.is-active) ~ .nav-popout--menu {
                display: block !important;
                opacity: 1 !important;
            }
        }
    }
}

@media all and (min-width: 651px) and (max-width: 899px) {
    .menu--structural .menu-content {
        overflow-x: auto;

        .nav-popout {
            .menu-separator:last-child {
                display: block !important;
            }
        }

        > .nav-popout > .nav-popout--menu {
            display: block !important;
            position: static !important;
            width: auto !important;
            border: none !important;
            box-shadow: none !important;
            opacity: 1 !important;
            transform: none !important;
            z-index: 0 !important;

            .nav-popout--menu {
                display: block !important;
                position: static !important;
                width: auto !important;
                border: none !important;
                box-shadow: none !important;
                opacity: 1 !important;
                transform: none !important;
            }
        }

        .nav-container a.offCanvasMenu-link.offCanvasMenu-link--splitToggle {
            display: none !important;
        }
    }
}

@media all and (min-width: 900px) and (max-width: 1199px) {
    .menu--structural .menu-content {
        .nav-container > a.u-indentDepth1 { text-indent: 0em; }
        .nav-container > a.u-indentDepth2 { text-indent: 1em; }
        .nav-container > a.u-indentDepth3 { text-indent: 2em; }
        .nav-container > a.u-indentDepth4 { text-indent: 3em; }

        > .nav-popout > .nav-popout--menu {
            right: -250px;
            max-height: 80vh;
            overflow-y: auto;

            .nav-popout {
                .menu-separator:last-child {
                    display: block !important;
                }
            }

            .nav-popout:hover > .nav-popout--menu {
                right: -250px;
                top: 100%;
                z-index: 20;
            }

            .nav-popout--menu {
                display: block !important;
                position: static !important;
                width: auto !important;
                border: none !important;
                box-shadow: none !important;
                opacity: 1 !important;
                transform: none !important;
                max-height: inherit;
                overflow-y: inherit;
            }

            .nav-container a.offCanvasMenu-link.offCanvasMenu-link--splitToggle {
                display: none !important;
            }
        }
    }
}

@media all and (min-width: 1200px) and (max-width: 1499px) {
    .menu--structural .menu-content {
        .nav-container > a.u-indentDepth1 { text-indent: 0em; }
        .nav-container > a.u-indentDepth2 { text-indent: 0em; }
        .nav-container > a.u-indentDepth3 { text-indent: 1em; }
        .nav-container > a.u-indentDepth4 { text-indent: 2em; }

        > .nav-popout .nav-popout--menu > .nav-popout .nav-popout--menu {
            right: -250px;
            max-height: 80vh;
            overflow-y: auto;

            .nav-popout {
                .menu-separator:last-child {
                    display: block !important;
                }
            }

            .nav-popout:hover > .nav-popout--menu {
                right: -250px;
                top: 100%;
                z-index: 20;
            }

            .nav-popout--menu {
                display: block !important;
                position: static !important;
                width: auto !important;
                border: none !important;
                box-shadow: none !important;
                opacity: 1 !important;
                transform: none !important;
                max-height: inherit;
                overflow-y: inherit;
            }

            .nav-container a.offCanvasMenu-link.offCanvasMenu-link--splitToggle {
                display: none !important;
            }
        }
    }
}

@media all and (min-width: 1500px) {
    .menu--structural .menu-content {
        .nav-container > a.u-indentDepth1 { text-indent: 0em; }
        .nav-container > a.u-indentDepth2 { text-indent: 0em; }
        .nav-container > a.u-indentDepth3 { text-indent: 0em; }
        .nav-container > a.u-indentDepth4 { text-indent: 1em; }

        > .nav-popout .nav-popout--menu > .nav-popout .nav-popout--menu > .nav-popout .nav-popout--menu {
            right: -250px;

            .nav-popout {
                .menu-separator:last-child {
                    display: block !important;
                }
            }

            .nav-popout:hover > .nav-popout--menu {
                right: -250px;
                top: 100%;
                z-index: 20;
            }

            .nav-popout--menu {
                display: block !important;
                position: static !important;
                width: auto !important;
                border: none !important;
                box-shadow: none !important;
                opacity: 1 !important;
                transform: none !important;
            }

            .nav-container a.offCanvasMenu-link.offCanvasMenu-link--splitToggle {
                display: none !important;
            }
        }
    }
}

/* [BZ] MenuFlex Tiered Menu END */
